<template><section><h1>Step 3 — Resume + Feedback + Save</h1><pre class="text-xs bg-gray-100 p-2">{{ s.recipe }}</pre><form @submit.prevent="save"><input v-model.number="f.sweet" type="number" placeholder="sweet 0-100" class="border p-2 w-full"/><input v-model.number="f.acid" type="number" placeholder="acid 0-100" class="border p-2 w-full mt-2"/><input v-model.number="f.body" type="number" placeholder="body 0-100" class="border p-2 w-full mt-2"/><button class="bg-black text-white px-4 py-2 mt-2">Save</button></form></section></template>
